// The dashboard's view snapshots are generated by `bun run golden`, from the recorded fixtures with the golden run among
// them. This test fails while they are stale: it renders every view afresh and compares each with the committed one,
// byte for byte, naming each file that differs, is missing, or is no view at all.
import { afterAll, expect, test } from 'bun:test';
import { cpSync, existsSync, mkdtempSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { renderDashboardViews } from '../../scripts/golden';

const COMMITTED = join(import.meta.dir, '..', 'fixtures', 'dashboard', 'views');
const temp = mkdtempSync(join(tmpdir(), 'sail-dashboard-views-'));
afterAll(() => rmSync(temp, { recursive: true, force: true }));

const REGENERATE = 'run bun run golden';
const filesIn = (dir: string) => (existsSync(dir) ? readdirSync(dir).sort() : []);

/** Every way the views in `stored` are not the views in `rendered`, each naming its file. */
function stale(rendered: string, stored: string): string[] {
  const [made, kept] = [filesIn(rendered), filesIn(stored)];
  return [
    ...made.filter((file) => !kept.includes(file)).map((file) => `${file} is missing: ${REGENERATE}`),
    ...kept.filter((file) => !made.includes(file)).map((file) => `${file} is no view: ${REGENERATE}`),
    ...made
      .filter((file) => kept.includes(file))
      .filter((file) => readFileSync(join(rendered, file), 'utf8') !== readFileSync(join(stored, file), 'utf8'))
      .map((file) => `${file} is stale: ${REGENERATE}`),
  ];
}

test('the committed dashboard views are what the fixtures render now', async () => {
  const fresh = join(temp, 'fresh');
  expect(await renderDashboardViews(fresh)).toEqual([
    'sidebar.html',
    'list-inbox.html',
    'list-active.html',
    'list-history.html',
    'list-history-selected.html',
    'list-queues.html',
    'list-queues-problem.html',
    'list-queues-held.html',
    'queue.html',
    'queue-watched.html',
    'menu-item.html',
    'run-golden.html',
    'run-fake-2.html',
    'list-menu-fake-2.html',
    'dialog-clean.html',
    'dialog-clean-several.html',
    'menu-fake-2.html',
    'dialog-restart.html',
    'run-fake-3.html',
    'list-menu-fake-3.html',
    'run-review.html',
    'toasts.html',
    'inspector-fake-2-implement-1-permissions.html',
    'inspector-golden-implement-2-overview.html',
    'inspector-golden-implement-2-files.html',
    'inspector-golden-tests-1-log.html',
    'inspector-golden-publish-1-log.html',
    'timeline-golden-publish-1.html',
    'timeline-claude-code-implement-1.html',
    'dense-sidebar.html',
    'dense-active.html',
    'dense-history.html',
    'dense-queues.html',
    'dense-menu-title.html',
    'dense-menu-key.html',
  ]);
  expect(stale(fresh, COMMITTED)).toEqual([]);
});

test("the dense fixture's recorded menu shows a title query's runs by key and title, and a key query's one run", () => {
  const title = readFileSync(join(COMMITTED, 'dense-menu-title.html'), 'utf8');
  expect(title).toContain('<span class="cmdk-key">FAKE-1001</span>');
  expect(title).toContain('<span class="cmdk-label">Retry the fetch helper on a 503</span>');
  expect(title).not.toContain('01M7D');
  const runTitles = [...title.matchAll(/<span class="cmdk-key">[^<]*<\/span><span class="cmdk-label">([^<]*)</g)];
  expect(runTitles.length).toBeGreaterThan(0);
  for (const [, label] of runTitles) expect(label?.toLowerCase()).toContain('retry');
  const key = readFileSync(join(COMMITTED, 'dense-menu-key.html'), 'utf8');
  const goto = key.slice(key.indexOf('<div class="cmdk-grp">go to</div>'));
  const next = goto.indexOf('<div class="cmdk-grp">', 10);
  const rows = (next < 0 ? goto : goto.slice(0, next)).match(/class="cmdk-row/g);
  expect(rows).toHaveLength(1);
  expect(key).toContain('<span class="st p-fail"></span><span class="cmdk-key">FAKE-2004</span>');
  expect(key).toContain('<span class="cmdk-hint">borealis › ticket-to-pr</span>');
});

test("the committed paused, held, watched queue's row holds both chips, an enabled poll and an unwatch", () => {
  const row = readFileSync(join(COMMITTED, 'list-queues-held.html'), 'utf8');
  expect(row).toContain('paused: ticketSource fake: the provider did not answer');
  expect(row).toMatch(/held until \d\d:\d\d:\d\d: usage limit/);
  expect(row).toContain('data-action="poll-queue" data-repo="beta" data-workflow="ticket-to-pr"');
  expect(row).toContain('data-action="unwatch" data-repo="beta" data-workflow="ticket-to-pr"');
  expect(row).toContain('watched</span>');
});

test('a view changed by one byte is named as stale, and so is one missing', async () => {
  const fresh = join(temp, 'again');
  await renderDashboardViews(fresh);
  const changed = join(temp, 'changed');
  cpSync(COMMITTED, changed, { recursive: true });
  const sidebar = readFileSync(join(changed, 'sidebar.html'), 'utf8');
  writeFileSync(join(changed, 'sidebar.html'), sidebar.replace('alpha', 'alphA'));
  rmSync(join(changed, 'queue.html'));
  expect(stale(fresh, changed)).toEqual([
    `queue.html is missing: ${REGENERATE}`,
    `sidebar.html is stale: ${REGENERATE}`,
  ]);
});

test('no golden view holds a checkbox', () => {
  const files = filesIn(COMMITTED);
  expect(files.length).toBeGreaterThan(20);
  expect(files.filter((file) => readFileSync(join(COMMITTED, file), 'utf8').includes('type="checkbox"'))).toEqual([]);
});
